from sympy import *
from sympy.abc import a

M = Matrix([[i + a*j for i in range(6)] for j in range(6)])

def _find_pivot(l):
    for pos, val in enumerate(l):
        if val:
            return (pos, val, None, None)
    return (None, None, None, None)

def bareiss(mat, cumm=1, depth=0):
    if mat.rows == 0:
        return S.One
    elif mat.rows == 1:
        return mat[0, 0]
    pivot_pos, pivot_val, _, _ = _find_pivot(mat[:, 0])
    print('  '*depth + 'rows=%s pivot_pos=%s pivot_val=%s cumm=%s' % (mat.rows, pivot_pos, pivot_val, cumm))
    if pivot_pos == None:
        return S.Zero
    sign = (-1) ** (pivot_pos % 2)
    rows = list(i for i in range(mat.rows) if i != pivot_pos)
    cols = list(range(mat.cols))
    tmp_mat = mat.extract(rows, cols)
    def entry(i, j):
        ret = (pivot_val*tmp_mat[i, j + 1] - mat[pivot_pos, j + 1]*tmp_mat[i, 0]) / cumm
        if not ret.is_Atom:
            ret = cancel(ret)
        return ret
    return sign*bareiss(mat._new(mat.rows - 1, mat.cols - 1, entry), pivot_val, depth+1)

try:
